SELECT COUNT(DISTINCT(A.PROD_NO)) FROM TBL_PRODUCT A LEFT JOIN TBL_CATEGORY B ON(A.CATEGORY_NO = B.CATEGORY_NO) LEFT JOIN TBL_BRAND C ON(A.BRAND_CD = C.BRAND_CD) LEFT JOIN TBL_OPTION_COMB O ON(A.PROD_NO = O.PROD_NO) WHERE A.USE_YN = 'Y'
AND A.CATEGORY_NO IN ( SELECT CATEGORY_NO FROM TBL_CATEGORY START WITH CATEGORY_NM = #{section} CONNECT BY PRIOR CATEGORY_NO = UP_CATEGORY_NO )
AND C.BRAND_NM = #{ brand }

SELECT * FROM( SELECT D.RANK AS RK, D.* FROM( SELECT DENSE_RANK() OVER (ORDER BY A.INS_DT DESC, A.PROD_NO DESC) RANK , A.PROD_NO , A.PROD_NM , A.PRICE , A.DISCOUNT_RATE , A.PROD_DESC , A.PROD_DETAIL_CONTENT , A.INS_DT , A.UPT_DT , A.USE_YN , B.CATEGORY_NM , C.BRAND_NM FROM TBL_PRODUCT A INNER JOIN TBL_CATEGORY B ON A.CATEGORY_NO = B.CATEGORY_NO INNER JOIN TBL_BRAND C ON A.BRAND_CD = C.BRAND_CD WHERE 1 = 1
) D
WHERE D.RANK <= #{ currentPageNo } * #{ recordsPerPage } )E WHERE E.RK > (#{ currentPageNo } - 1) * #{ recordsPerPage }

SELECT * FROM( SELECT D.RANK AS RK, D.* FROM( SELECT DENSE_RANK() OVER (ORDER BY A.INS_DT DESC, A.PROD_NO DESC) RANK , A.PROD_NM , A.PRICE , A.DISCOUNT_RATE , A.PROD_DESC , A.PROD_DETAIL_CONTENT , A.INS_DT , A.UPT_DT , A.USE_YN , B.CATEGORY_NM , C.BRAND_NM FROM TBL_PRODUCT A INNER JOIN TBL_CATEGORY B ON A.CATEGORY_NO = B.CATEGORY_NO INNER JOIN TBL_BRAND C ON A.BRAND_CD = C.BRAND_CD WHERE A.USE_YN = 'Y'
) D
WHERE D.RANK <= #{ currentPageNo } * #{ recordsPerPage } )E WHERE E.RK > (#{ currentPageNo } - 1) * #{ recordsPerPage }

SELECT F.* FROM(SELECT E.RANK RK , E.* FROM (SELECT
ROW_NUMBER() OVER (ORDER BY ) RANK
, D.* FROM (SELECT DISTINCT(A.PROD_NO) , A.PRICE , A.PROD_DESC , A.INS_DT , RW.REVIEWED AS PROD_REVIEW_COUNT , RW.RATED AS PROD_RATINGS FROM TBL_PRODUCT A LEFT JOIN TBL_CATEGORY B ON(A.CATEGORY_NO = B.CATEGORY_NO) LEFT JOIN TBL_BRAND C ON(A.BRAND_CD = C.BRAND_CD) LEFT JOIN TBL_REVIEW D ON (A.PROD_NO = D.PROD_NO) LEFT JOIN (SELECT AA.PROD_NO , COUNT(RR.REVIEW_NO) AS REVIEWED , NVL(AVG(RR.REVW_RATINGS), 0) AS RATED FROM TBL_PRODUCT AA LEFT JOIN TBL_OPTION_COMB OO ON(OO.PROD_NO = AA.PROD_NO) LEFT JOIN TBL_REVIEW RR ON (RR.OPT_COMB_NO = OO.OPT_COMB_NO) GROUP BY AA.PROD_NO)RW ON (A.prod_No = RW.PROD_NO) WHERE A.USE_YN = 'Y'
AND B.CATEGORY_NO IN (SELECT CATEGORY_NO FROM TBL_CATEGORY START WITH CATEGORY_NO = #{ category } CONNECT BY PRIOR CATEGORY_NO = UP_CATEGORY_NO)
) D ) E
WHERE E.RANK <= #{ page } * #{ items }) F WHERE F.RK > (#{ page } - 1) * #{ items }

