INSERT
INTO TBL_PRODUCT
(
PROD_NO
,PROD_NM
,BRAND_CD
,CATEGORY_NO
,PRICE
,DISCOUNT_RATE
,PROD_DESC
,PROD_DETAIL_CONTENT
,INS_DT
,UPT_DT
,USE_YN
)
VALUES
(
SEQ_PROD_NO.NEXTVAL
,
#{ prodNm }
, #{ brandCd }
, #{ categoryNo }
, #{ price }
, #{ discountRate }
, #{ prodDesc }
, #{ prodDetailContent }
, SYSDATE
, SYSDATE
, DEFAULT
)

