, ORIG_FILE_NM
, SAVE_FILE_NM
, SAVE_PATH
,
THUMBNAIL_PATH
, FILE_TYPE
, ATTACH_STATUS_YN
)
VALUES
(
SEQ_ATTACH_NO.NEXTVAL
, #{ refProdNo }
, NULL
, NULL
, #{ origFileNm }
, #{
saveFileNm }
, #{ savePath }
, #{ thumbnailPath }
, #{ fileType }
,
DEFAULT
)


